-- 📚 꼭집 주거 사전 — 행복주택 최대 거주기간 — 대학생·청년 10년 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 3.5초 · 결과:
-- {"anns": 29, "by_std": {"행복주택": 24, "행복주택(신혼희망)": 5}, "청년10": 9, "청년10_ex": ["2015122300020871", "2015122300020870", "2015122300020858"], "합산10": 2, "합산10_ex": ["20648_1_경기도_광명시", "20647_1_경기도_광명시"], "연장2년": 14, "연장2년_ex": ["2015122300020871", "2015122300020870", "2015122300020859"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' group by 1)q),'청년10',(select count(distinct announcement_id) from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'대학생\s*,?\s*청년\s*(계층)?\s*[/:]?\s*(최대\s*거주기간\s*:\s*)?10\s*년'),'청년10_ex',(select json_agg(i) from(select distinct announcement_id i from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'대학생\s*,?\s*청년\s*(계층)?\s*[/:]?\s*(최대\s*거주기간\s*:\s*)?10\s*년' order by 1 desc limit 3)q),'합산10',(select count(distinct announcement_id) from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'합산한\s*기간은\s*10\s*년'),'합산10_ex',(select json_agg(i) from(select distinct announcement_id i from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'합산한\s*기간은\s*10\s*년' order by 1 desc limit 3)q),'연장2년',(select count(distinct announcement_id) from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'예비입주자가\s*없거나[^.]{0,80}2\s*년\s*(씩\s*)?연장'),'연장2년_ex',(select json_agg(i) from(select distinct announcement_id i from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'예비입주자가\s*없거나[^.]{0,80}2\s*년\s*(씩\s*)?연장' order by 1 desc limit 3)q))j;
